.ds-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;min-height:42px;padding:10px 15px;border:1px solid transparent;border-radius:9px;font:640 13px/1.15 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);transition:color .14s ease, background-color .14s ease, border-color .14s ease}
.ds-button:active{transform:translateY(1px)}
.ds-button:disabled{cursor:not-allowed;transform:none;opacity:.58}
.ds-button-primary{color:#fff;background:var(--teal-700,#087b83)}
.ds-button-primary:hover{color:#fff;background:#05656c}
@media (max-width: 560px){.ds-button{min-height:44px}}
.ds-button:focus-visible{outline:3px solid var(--teal-700,#087b83);outline-offset:3px}
@media(prefers-reduced-motion:reduce){.ds-button{animation:none!important;transition:none!important}}

.ds-dashboard-summary{font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);display:grid;grid-template-columns:minmax(0, .92fr) minmax(0, 1.38fr);gap:22px;margin:0 0 26px}
.ds-summary-group{min-width:0}
.ds-summary-group--actions{padding-left:22px;border-left:1px solid var(--line,#d4dee7)}
.ds-summary-group-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:28px;margin-bottom:8px}
.ds-summary-group-label{color:var(--ink-800,#344d63);font:650 12px/1.3 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);letter-spacing:.01em}
.ds-summary-group-context{color:var(--ink-500,#61788b);font:11px/1.3 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-dashboard-summary .ds-metric-grid{display:grid;gap:9px;margin:0;padding:0;border:0;border-radius:0;background:transparent}
.ds-dashboard-summary .ds-metric-grid-state{grid-template-columns:repeat(2, minmax(0, 1fr))}
.ds-dashboard-summary .ds-metric-grid-actions{grid-template-columns:repeat(3, minmax(0, 1fr))}
.ds-dashboard-summary .ds-metric-card{position:relative;display:block;flex:initial;min-width:0;min-height:105px;padding:14px 15px;border:1px solid var(--line,#d4dee7);border-radius:10px;color:var(--ink-950,#172a3b);background:var(--surface-raised,#ffffff);box-shadow:none}
.ds-dashboard-summary .ds-metric-card:hover{background:#f8fbfd;border-color:#9fb6c4}
.ds-dashboard-summary .ds-metric-card > div:last-child{display:block;min-width:0}
.ds-dashboard-summary .ds-metric-value{margin:2px 36px 8px 0;color:var(--navy-950,#10223a);font:650 29px/1 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);font-variant-numeric:tabular-nums}
.ds-dashboard-summary .ds-metric-label{margin:0;color:var(--ink-800,#344d63);font:620 12px/1.35 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-dashboard-summary .ds-metric-note{margin-top:3px;color:var(--ink-500,#61788b);font:11px/1.35 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
@media (max-width: 1150px){.ds-dashboard-summary{grid-template-columns:1fr;gap:15px}
.ds-summary-group--actions{padding:14px 0 0;border-top:1px solid var(--line,#d4dee7);border-left:0}}
@media (max-width: 850px){.ds-dashboard-summary{gap:12px}}
@media (max-width: 560px){.ds-summary-group-heading{align-items:baseline}
.ds-summary-group-label{font-size:11px}
.ds-summary-group-context{font-size:10px}
.ds-dashboard-summary .ds-metric-grid-actions{grid-template-columns:repeat(2, minmax(0, 1fr))}
.ds-dashboard-summary .ds-metric-card{min-height:102px;padding:12px}
.ds-dashboard-summary .ds-metric-value{font-size:26px}}
.ds-dashboard-summary .ds-metric-total{background:var(--navy-900,#152c49);border-color:var(--navy-900,#152c49)}
.ds-dashboard-summary .ds-metric-total .ds-metric-value,.ds-dashboard-summary .ds-metric-total .ds-metric-label{color:#fff}
.ds-dashboard-summary .ds-metric-total .ds-metric-note{color:#c1d0dc}.ds-dashboard-summary{grid-template-columns:2fr 3fr;border-block:1px solid #dfe6ed;padding:22px 0 28px}.ds-dashboard-summary .ds-metric-card,.ds-dashboard-summary .ds-metric-total{padding:0;min-height:0;border:0;background:transparent;border-radius:0}.ds-dashboard-summary .ds-metric-card .ds-metric-value{color:#152c49;font-size:44px;font-weight:550;line-height:1;margin:0 0 12px}.ds-dashboard-summary .ds-metric-card .ds-metric-label{color:#21374e;font-size:13px;font-weight:550}.ds-dashboard-summary .ds-metric-card .ds-metric-note{color:#627487;font-size:11px}@media(max-width:1000px){.ds-dashboard-summary{grid-template-columns:1fr}}

