.ds-field{font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);color:var(--ink-950,#172a3b);display:grid;gap:5px;min-width:140px;flex:1}
.ds-field label{color:var(--ink-800,#344d63);font:620 11px/1.35 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-field input{width:100%;min-height:42px;padding:9px 11px;border:1px solid #a9bab7;border-radius:8px;color:var(--ink-950,#172a3b);background:var(--surface-raised,#ffffff);font:13px/1.45 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);border-color:#b9c8d3}
