@media (max-width: 560px){.ds-field input{font-size:16px}}
.ds-field input:focus-visible{outline:3px solid var(--teal-700,#087b83);outline-offset:3px}
@media(prefers-reduced-motion:reduce){.ds-field input{animation:none!important;transition:none!important}}

.ds-rail{display:grid;gap:3px;width:248px;padding:25px 15px 18px;background:var(--navy-950,#10223a);font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-nav-link{text-decoration:none;display:flex;align-items:center;font-family:var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);position:relative;min-height:46px;gap:12px;padding:9px 11px;border:1px solid transparent;border-radius:9px;color:#c5d5e2;font-size:13px;font-weight:610;transition:background-color .16s ease, color .16s ease}
.ds-nav-link:hover{color:#fff;background:#19334c}
.ds-nav-link.ds-active{color:#fff;background:#203e58;box-shadow:none;border-color:#3c5c76}
.ds-nav-link.ds-active::before{content:"";position:absolute;top:10px;bottom:10px;left:6px;width:2px;border-radius:2px;background:var(--stamp-light,#a4d8d5)}
.ds-nav-link:focus-visible{outline:3px solid var(--teal-700,#087b83);outline-offset:3px}
