.ds-panel{font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);color:var(--ink-950,#172a3b);min-width:0;overflow:hidden;border:1px solid var(--line,#d4dee7);border-radius:12px;background:var(--surface-raised,#ffffff);box-shadow:none}
.ds-panel-title{margin:0;font-family:var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);color:var(--ink-950,#172a3b);font-size:15px;font-weight:600}
.ds-panel-header{display:flex;align-items:center;justify-content:space-between;min-height:50px;flex-wrap:wrap;gap:10px;padding:12px 15px;border-bottom:1px solid var(--line,#d4dee7)}
.ds-panel-body{padding:15px}
@media (max-width: 560px){.ds-panel-header{flex-wrap:wrap;padding-inline:14px}
.ds-panel-body{padding-inline:14px}}

.ds-queue-entry{font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);text-decoration:none;display:grid;align-items:center;position:relative;padding:14px 12px;border-bottom:1px solid var(--line,#d4dee7);color:var(--ink-950,#172a3b);background:transparent;transition:color .16s ease, background-color .16s ease;grid-template-columns:84px minmax(0, 1fr) 118px;gap:10px;min-height:69px;padding-inline:8px;border-color:var(--line-soft,#e6edf2)}
.ds-queue-state{display:flex;align-items:center;justify-content:flex-start;gap:8px;font:620 11px/1.35 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);color:var(--amber,#76520d)}
.ds-queue-entry:hover{background:#f7fafc}
.ds-queue-entry.ds-selected{color:var(--ink-950,#172a3b);outline:1px solid #c7b58f;outline-offset:-1px;background:#e8f3f2;outline-color:#a9cecb}
.ds-queue-entry.ds-selected::after{content:"";position:absolute;top:19px;right:10px;width:6px;height:6px;border-radius:50%;background:var(--teal-700,#087b83)}
.ds-queue-entry strong{display:block;color:inherit;font:620 14px/1.25 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-queue-entry small{display:block;margin-top:4px;color:var(--ink-650,#50697d);font-size:11px;line-height:1.35}
.ds-queue-entry.ds-selected small{color:var(--ink-650,#50697d)}
.ds-queue-source strong{font:600 12px/1.25 var(--font-data,Inter, "Segoe UI", system-ui, sans-serif);letter-spacing:-.03em}
.ds-queue-entry.ds-selected .ds-queue-state{color:#05656c}
@media (max-width: 560px){.ds-queue-entry{gap:9px;min-height:76px;padding:12px 8px;grid-template-columns:70px minmax(0, 1fr);padding-inline:6px}
.ds-queue-entry strong{font-size:13px}
.ds-queue-entry small{font-size:10px}
.ds-queue-state{font-size:10px;grid-column:2;margin-top:-6px}}
.ds-queue-entry:focus-visible{outline:3px solid var(--teal-700,#087b83);outline-offset:3px}
@media(prefers-reduced-motion:reduce){.ds-queue-entry{animation:none!important;transition:none!important}}

.ds-evidence-folio{font:15px/1.55 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);min-width:0;scroll-margin-top:84px;padding:0 22px 20px;border:1px solid var(--line,#d4dee7);border-top:3px solid var(--teal-700,#087b83);border-radius:12px;background:#fff;box-shadow:0 8px 24px rgba(17, 38, 61, .07)}
.ds-folio-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;font:11px/1.4 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);font-variant-numeric:tabular-nums;margin:0 -23px 18px;padding:12px 21px;border-bottom:1px solid var(--line-soft,#e6edf2);border-radius:9px 9px 0 0;color:var(--ink-650,#50697d);background:#f5f8fb;font-size:11px}
.ds-folio-meta strong{padding:5px 8px;border-radius:4px;color:#fff;background:var(--navy-800,#264761);font:600 11px/1.2 var(--font-data,Inter, "Segoe UI", system-ui, sans-serif)}
.ds-evidence-folio h2{margin:0 0 11px;color:var(--ink-950,#172a3b);font:600 23px/1.25 var(--font-ui,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);font-size:20px;font-weight:650;letter-spacing:-.025em}
.ds-folio-quote{max-height:245px;margin:0 0 20px;overflow-y:auto;color:var(--ink-950,#172a3b);font:18px/1.62 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif);overflow-wrap:anywhere;padding-left:15px;border-left:3px solid var(--teal-700,#087b83);font-size:17px;line-height:1.55}
.ds-folio-quote mark{padding:1px 3px;color:inherit;border-radius:2px;text-decoration:none;box-decoration-break:clone;-webkit-box-decoration-break:clone;background:var(--evidence-mark,#d7efeb)}
.ds-folio-facts{margin:0 0 17px;border-top:1px solid var(--line,#d4dee7);color:var(--ink-950,#172a3b);font-size:12px;border-color:var(--line,#d4dee7)}
.ds-folio-facts > div{display:grid;grid-template-columns:minmax(100px,.8fr) minmax(0,1.2fr);gap:12px;padding:11px 0;border-bottom:1px solid var(--line-soft,#e6edf2);padding-block:10px}
.ds-folio-facts dt{color:var(--ink-650,#50697d)}
.ds-folio-facts dd{margin:0;font-weight:650}
.ds-folio-facts small{display:block;color:var(--ink-650,#50697d);font:11px/1.4 var(--font-body,Inter, "Segoe UI Variable", "Segoe UI", Roboto, system-ui, sans-serif)}
.ds-folio-note{margin:10px 0 0;font-size:11px;line-height:1.55;color:var(--ink-500,#61788b)}
@media (min-width: 851px) and (max-width: 1150px){.ds-evidence-folio{order:-1}}
@media (max-width: 850px){.ds-evidence-folio{display:block;order:0}}
@media (max-width: 560px){.ds-evidence-folio{padding:0 15px 16px}
.ds-folio-meta{margin:0 -17px 15px;padding:12px 16px;font-size:10px;margin-inline:-16px;padding-inline:14px}
.ds-evidence-folio h2{margin-top:14px;font-size:21px}
